import { sql } from "drizzle-orm";
import {
  boolean,
  check,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  primaryKey,
  smallint,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

// Conventions: money is integer paise, timestamps are UTC `timestamptz`,
// ids are uuid v4 generated by Postgres.

const id = () => uuid("id").primaryKey().defaultRandom();
const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
const updatedAt = () => timestamp("updated_at", { withTimezone: true }).notNull().defaultNow();

// ---------------------------------------------------------------------------
// Identity
// ---------------------------------------------------------------------------

export const users = pgTable("users", {
  id: id(),
  phone: text("phone").unique(),
  email: text("email").unique(),
  name: text("name"),
  createdAt: createdAt(),
});

export const addresses = pgTable(
  "addresses",
  {
    id: id(),
    userId: uuid("user_id").notNull().references(() => users.id),
    name: text("name").notNull(),
    phone: text("phone").notNull(),
    line1: text("line1").notNull(),
    line2: text("line2"),
    city: text("city").notNull(),
    state: text("state").notNull(),
    pincode: text("pincode").notNull(),
    createdAt: createdAt(),
  },
  (t) => [index("addresses_user_idx").on(t.userId)],
);

// ---------------------------------------------------------------------------
// Sellers
// ---------------------------------------------------------------------------

export const sellerTrack = pgEnum("seller_track", ["STORE", "CLOSET"]);
export const sellerStatus = pgEnum("seller_status", ["APPLIED", "APPROVED", "REJECTED", "SUSPENDED"]);
export const kycStatus = pgEnum("kyc_status", ["NOT_STARTED", "PENDING", "VERIFIED", "FAILED"]);

export const sellers = pgTable("sellers", {
  id: id(),
  userId: uuid("user_id").notNull().unique().references(() => users.id),
  track: sellerTrack("track").notNull(),
  status: sellerStatus("status").notNull().default("APPLIED"),
  kycStatus: kycStatus("kyc_status").notNull().default("NOT_STARTED"),
  /** URL slug, e.g. yolt.in/s/thrifttrove */
  handle: text("handle").notNull().unique(),
  displayName: text("display_name").notNull(),
  bio: text("bio"),
  logoUrl: text("logo_url"),
  bannerUrl: text("banner_url"),
  instagramHandle: text("instagram_handle"),
  instagramVerifiedAt: timestamp("instagram_verified_at", { withTimezone: true }),
  gstin: text("gstin"),
  /** Pickup state; used if unregistered sellers must be limited to intra-state sales (legal check L2). */
  pickupState: text("pickup_state"),
  shippingFeePaise: integer("shipping_fee_paise").notNull().default(0),
  freeShippingAbovePaise: integer("free_shipping_above_paise"),
  dispatchDays: smallint("dispatch_days").notNull().default(2),
  sizeReturnsDefault: boolean("size_returns_default").notNull().default(false),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

// ---------------------------------------------------------------------------
// Drops
// ---------------------------------------------------------------------------

export const dropStatus = pgEnum("drop_status", ["DRAFT", "SCHEDULED", "LIVE", "ENDED", "CANCELLED"]);

export const drops = pgTable(
  "drops",
  {
    id: id(),
    sellerId: uuid("seller_id").notNull().references(() => sellers.id),
    title: text("title").notNull(),
    coverUrl: text("cover_url"),
    startsAt: timestamp("starts_at", { withTimezone: true }).notNull(),
    status: dropStatus("status").notNull().default("DRAFT"),
    maxHoldsPerBuyer: smallint("max_holds_per_buyer").notNull().default(2),
    createdAt: createdAt(),
  },
  (t) => [index("drops_seller_idx").on(t.sellerId), index("drops_starts_idx").on(t.startsAt)],
);

// ---------------------------------------------------------------------------
// Catalog
// ---------------------------------------------------------------------------

export const listingStatus = pgEnum("listing_status", [
  "DRAFT",
  "SCHEDULED", // in an upcoming drop ("Coming soon")
  "AVAILABLE",
  "RESERVED", // an active hold exists
  "PAYMENT_PENDING", // hold owner has started paying
  "SOLD",
  "SOLD_ELSEWHERE", // seller sold it on Instagram / in person
  "WITHDRAWN",
]);

export const conditionGrade = pgEnum("condition_grade", ["NEW_WITH_TAGS", "LIKE_NEW", "GOOD", "FAIR"]);

export const photoKind = pgEnum("photo_kind", ["FRONT", "BACK", "LABEL", "FLAW", "DETAIL", "PROOF_OF_PURCHASE"]);

/**
 * Measurements in centimetres. `chestCm` etc. state whether they are flat (one side)
 * or around; never fabricated — missing means unknown.
 */
export type Measurements = {
  basis?: "FLAT" | "AROUND";
  chestCm?: number;
  waistCm?: number;
  lengthCm?: number;
  shoulderCm?: number;
  sleeveCm?: number;
  inseamCm?: number;
  hipCm?: number;
  footLengthCm?: number;
};

export const listings = pgTable(
  "listings",
  {
    id: id(),
    sellerId: uuid("seller_id").notNull().references(() => sellers.id),
    dropId: uuid("drop_id").references(() => drops.id),
    slug: text("slug").notNull().unique(),
    title: text("title").notNull(),
    description: text("description"),
    category: text("category").notNull(),
    brandDeclared: text("brand_declared"),
    tagSize: text("tag_size"),
    measurements: jsonb("measurements").$type<Measurements>().notNull().default({}),
    condition: conditionGrade("condition").notNull(),
    flaws: text("flaws"),
    /** Seller explicitly ticked "no flaws" — an empty flaws field alone is not enough. */
    noFlawsConfirmed: boolean("no_flaws_confirmed").notNull().default(false),
    pricePaise: integer("price_paise").notNull(),
    currency: text("currency").notNull().default("INR"),
    status: listingStatus("status").notNull().default("DRAFT"),
    /** The hold that currently owns this item. Acts as the generation token for releases. */
    currentHoldId: uuid("current_hold_id"),
    sizeReturnsAllowed: boolean("size_returns_allowed").notNull().default(false),
    allowOffers: boolean("allow_offers").notNull().default(false),
    publishedAt: timestamp("published_at", { withTimezone: true }),
    soldAt: timestamp("sold_at", { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("listings_seller_status_idx").on(t.sellerId, t.status),
    index("listings_status_published_idx").on(t.status, t.publishedAt),
    check("listings_price_positive", sql`${t.pricePaise} > 0`),
    check(
      "listings_hold_matches_status",
      sql`(${t.currentHoldId} IS NULL) = (${t.status} NOT IN ('RESERVED', 'PAYMENT_PENDING'))`,
    ),
  ],
);

export const listingPhotos = pgTable(
  "listing_photos",
  {
    id: id(),
    listingId: uuid("listing_id").notNull().references(() => listings.id, { onDelete: "cascade" }),
    url: text("url").notNull(),
    kind: photoKind("kind").notNull(),
    caption: text("caption"),
    position: smallint("position").notNull(),
  },
  (t) => [uniqueIndex("listing_photos_position_uq").on(t.listingId, t.position)],
);

// ---------------------------------------------------------------------------
// Holds (reservations)
// ---------------------------------------------------------------------------

export const holdStatus = pgEnum("hold_status", ["ACTIVE", "CONVERTED", "EXPIRED", "RELEASED"]);
export const holdSource = pgEnum("hold_source", ["CHECKOUT", "OFFER", "DROP_CLAIM"]);

export const holds = pgTable(
  "holds",
  {
    id: id(),
    listingId: uuid("listing_id").notNull().references(() => listings.id),
    buyerId: uuid("buyer_id").notNull().references(() => users.id),
    orderId: uuid("order_id").notNull(),
    source: holdSource("source").notNull(),
    status: holdStatus("status").notNull().default("ACTIVE"),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    createdAt: createdAt(),
    endedAt: timestamp("ended_at", { withTimezone: true }),
  },
  (t) => [
    // At most one active hold per garment, enforced by Postgres.
    uniqueIndex("holds_one_active_per_listing").on(t.listingId).where(sql`${t.status} = 'ACTIVE'`),
    index("holds_active_expiry_idx").on(t.expiresAt).where(sql`${t.status} = 'ACTIVE'`),
    index("holds_order_idx").on(t.orderId),
  ],
);

// ---------------------------------------------------------------------------
// Orders and payments
// ---------------------------------------------------------------------------

export const orderStatus = pgEnum("order_status", [
  "AWAITING_PAYMENT",
  "CONFIRMED",
  "PACKED",
  "SHIPPED",
  "DELIVERED",
  "CLOSED",
  "EXPIRED", // hold ran out before payment
  "CANCELLED_BY_BUYER",
  "CANCELLED_BY_SELLER",
  "NEEDS_REFUND", // paid, but the item could not be allocated (late payment)
]);

export type AddressSnapshot = {
  name: string;
  phone: string;
  line1: string;
  line2?: string | null;
  city: string;
  state: string;
  pincode: string;
};

export const orders = pgTable(
  "orders",
  {
    id: id(),
    /** Human-friendly reference shown to buyers and support, e.g. YL-7Q4K2M. */
    reference: text("reference").notNull().unique(),
    buyerId: uuid("buyer_id").notNull().references(() => users.id),
    sellerId: uuid("seller_id").notNull().references(() => sellers.id),
    status: orderStatus("status").notNull().default("AWAITING_PAYMENT"),
    subtotalPaise: integer("subtotal_paise").notNull(),
    shippingPaise: integer("shipping_paise").notNull(),
    platformFeePaise: integer("platform_fee_paise").notNull().default(0),
    totalPaise: integer("total_paise").notNull(),
    currency: text("currency").notNull().default("INR"),
    shippingAddress: jsonb("shipping_address").$type<AddressSnapshot>(),
    dispatchBy: timestamp("dispatch_by", { withTimezone: true }),
    confirmedAt: timestamp("confirmed_at", { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("orders_buyer_idx").on(t.buyerId, t.createdAt),
    index("orders_seller_idx").on(t.sellerId, t.status),
    check("orders_total_matches", sql`${t.totalPaise} = ${t.subtotalPaise} + ${t.shippingPaise} + ${t.platformFeePaise}`),
  ],
);

/** Immutable copy of the listing as the buyer saw it at checkout. */
export type ListingSnapshot = {
  title: string;
  category: string;
  brandDeclared: string | null;
  tagSize: string | null;
  measurements: Measurements;
  condition: string;
  flaws: string | null;
  sizeReturnsAllowed: boolean;
  photoUrl: string | null;
};

export const orderItems = pgTable(
  "order_items",
  {
    id: id(),
    orderId: uuid("order_id").notNull().references(() => orders.id),
    listingId: uuid("listing_id").notNull().references(() => listings.id),
    pricePaise: integer("price_paise").notNull(),
    snapshot: jsonb("snapshot").$type<ListingSnapshot>().notNull(),
    /** True once this garment is allocated to this order after payment. */
    allocated: boolean("allocated").notNull().default(false),
  },
  (t) => [
    uniqueIndex("order_items_order_listing_uq").on(t.orderId, t.listingId),
    // One garment can belong to at most one paid purchase — the last line of defence against overselling.
    uniqueIndex("order_items_one_allocation_per_listing").on(t.listingId).where(sql`${t.allocated}`),
  ],
);

export const paymentStatus = pgEnum("payment_status", ["CREATED", "PENDING", "SUCCEEDED", "FAILED", "UNKNOWN"]);

export const paymentAttempts = pgTable(
  "payment_attempts",
  {
    id: id(),
    orderId: uuid("order_id").notNull().references(() => orders.id),
    provider: text("provider").notNull(),
    providerOrderId: text("provider_order_id"),
    amountPaise: integer("amount_paise").notNull(),
    currency: text("currency").notNull().default("INR"),
    status: paymentStatus("status").notNull().default("CREATED"),
    providerPaymentId: text("provider_payment_id"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("payment_attempts_provider_order_uq").on(t.provider, t.providerOrderId),
    index("payment_attempts_order_idx").on(t.orderId),
  ],
);

/** Every provider webhook we accept, deduplicated by the provider's event id. */
export const paymentEvents = pgTable(
  "payment_events",
  {
    id: id(),
    provider: text("provider").notNull(),
    providerEventId: text("provider_event_id").notNull(),
    type: text("type").notNull(),
    payload: jsonb("payload").notNull(),
    receivedAt: timestamp("received_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [uniqueIndex("payment_events_provider_event_uq").on(t.provider, t.providerEventId)],
);

export const refundStatus = pgEnum("refund_status", ["REQUESTED", "PROCESSING", "SUCCEEDED", "FAILED"]);

export const refunds = pgTable(
  "refunds",
  {
    id: id(),
    orderId: uuid("order_id").notNull().references(() => orders.id),
    paymentAttemptId: uuid("payment_attempt_id").notNull().references(() => paymentAttempts.id),
    amountPaise: integer("amount_paise").notNull(),
    reason: text("reason").notNull(),
    status: refundStatus("status").notNull().default("REQUESTED"),
    providerRefundId: text("provider_refund_id"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("refunds_order_idx").on(t.orderId)],
);

// ---------------------------------------------------------------------------
// Trust and retention
// ---------------------------------------------------------------------------

export const reviews = pgTable(
  "reviews",
  {
    id: id(),
    orderItemId: uuid("order_item_id").notNull().unique().references(() => orderItems.id),
    sellerId: uuid("seller_id").notNull().references(() => sellers.id),
    buyerId: uuid("buyer_id").notNull().references(() => users.id),
    rating: smallint("rating").notNull(),
    accuracyRating: smallint("accuracy_rating"),
    body: text("body"),
    photoUrls: jsonb("photo_urls").$type<string[]>().notNull().default([]),
    sellerReply: text("seller_reply"),
    createdAt: createdAt(),
  },
  (t) => [
    index("reviews_seller_idx").on(t.sellerId, t.createdAt),
    check("reviews_rating_range", sql`${t.rating} BETWEEN 1 AND 5`),
  ],
);

export const savedItems = pgTable(
  "saved_items",
  {
    userId: uuid("user_id").notNull().references(() => users.id),
    listingId: uuid("listing_id").notNull().references(() => listings.id),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.listingId] })],
);

export const follows = pgTable(
  "follows",
  {
    userId: uuid("user_id").notNull().references(() => users.id),
    sellerId: uuid("seller_id").notNull().references(() => sellers.id),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.sellerId] })],
);

// ---------------------------------------------------------------------------
// Operations
// ---------------------------------------------------------------------------

/** Domain events written in the same transaction as the change; a job delivers them (notifications, search indexing). */
export const outboxEvents = pgTable(
  "outbox_events",
  {
    id: id(),
    type: text("type").notNull(),
    payload: jsonb("payload").notNull(),
    createdAt: createdAt(),
    processedAt: timestamp("processed_at", { withTimezone: true }),
  },
  (t) => [index("outbox_unprocessed_idx").on(t.createdAt).where(sql`${t.processedAt} IS NULL`)],
);

export const auditEvents = pgTable(
  "audit_events",
  {
    id: id(),
    actorId: uuid("actor_id"),
    actorRole: text("actor_role").notNull(),
    action: text("action").notNull(),
    entity: text("entity").notNull(),
    entityId: uuid("entity_id").notNull(),
    before: jsonb("before"),
    after: jsonb("after"),
    reason: text("reason"),
    createdAt: createdAt(),
  },
  (t) => [index("audit_entity_idx").on(t.entity, t.entityId)],
);
